                    return;
                }
                settings.value.ttsDefaultSpeaker = fallbackName;
                voiceName = fallbackName;
            }
            try {
                TTSManager.stop();
                await TTSManager.speak({ type: 'dialogue', speaker, text, tts: voiceName ? { speaker: voiceName } : undefined }, `desktop_pet_tts_test_${Date.now()}`);
